def shortestPathBinaryMatrix(grid):
    n = len(grid)
    if n == 0 or grid[0][0] == 1 or grid[n - 1][n - 1] == 1:
        return -1
    INF = 10 ** 9
    d = [[INF] * n for _ in range(n)]
    d[0][0] = 1
    changed = True
    while changed:
        changed = False
        for i in range(n):
            for j in range(n):
                if grid[i][j] == 0 and d[i][j] < INF:
                    for di in (-1, 0, 1):
                        for dj in (-1, 0, 1):
                            ni, nj = i + di, j + dj
                            if 0 <= ni < n and 0 <= nj < n and grid[ni][nj] == 0 and d[ni][nj] > d[i][j] + 1:
                                d[ni][nj] = d[i][j] + 1
                                changed = True
    return d[n - 1][n - 1] if d[n - 1][n - 1] < INF else -1

